DELETE `pg` FROM `pool_gameobject` `pg`
INNER JOIN `gameobject` `g` ON `g`.`guid` = `pg`.`guid`
WHERE `g`.`map` = 1048;
DELETE FROM `creature` WHERE `map` = 1048;
DELETE FROM `gameobject` WHERE `map` = 1048;

